<?php
/** Directly authorized full-result CSV or print. Completed spool before success. */
session_start();require_once __DIR__.'/db_connect.php';require_once __DIR__.'/includes/financial_export.php';header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');$spool=null;
try{
    if($_SERVER['REQUEST_METHOD']!=='GET'){header('Allow: GET');throw new ReportingProblem('Exports are read-only.',405);}
    $format=reporting_text($_GET['format']??'csv',8,'export format');if(!in_array($format,['csv','print','pdf','xlsx'],true))throw new ReportingProblem('Choose CSV, PDF, Excel or print.',400);
    $model=financial_export_model($pdo,(int)($_SESSION['UserID']??0),$_GET);$spool=financial_export_spool($model);
    if(session_status()===PHP_SESSION_ACTIVE)session_write_close();
    if(in_array($format,['pdf','xlsx'],true)){fclose($spool);$spool=null;require_once __DIR__.'/includes/report_export_binary.php';$spool=report_export_binary($model,$format);header('Content-Type: '.($format==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'));header('Content-Disposition: attachment; filename="'.preg_replace('/\.csv$/','',$model['filename']).'.'.$format.'"');header('Content-Length: '.fstat($spool)['size']);fpassthru($spool);fclose($spool);exit;}
    if($format==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$model['filename'].'"');header('Content-Length: '.fstat($spool)['size']);fpassthru($spool);fclose($spool);exit;}
    fclose($spool);$spool=null;$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
    $footer='Atikha Finance · '.$model['title'].' · '.(($model['metadata']['Frozen revision']??null)!==null?'Frozen revision '.$model['metadata']['Frozen revision']:'Live / all matching results');
    $sections=[];foreach($model['sections'] as $section){$columns=$section['columns'];if(count($columns)>10){$first=array_shift($columns);foreach(array_chunk($columns,8) as $n=>$chunk)$sections[]=array_replace($section,['title'=>$section['title'].' · section '.($n+1),'columns'=>array_merge([$first],$chunk)]);}else $sections[]=$section;}
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($model['title']) ?> — all results</title><link rel="stylesheet" href="assets/css/financial_reports.css"><link rel="stylesheet" href="assets/css/financial_export.css"><?php if(!empty($model['transaction_presentation'])): ?><link rel="stylesheet" href="assets/css/transaction_workspace.css?v=<?= filemtime(__DIR__.'/assets/css/transaction_workspace.css') ?>"><?php endif; ?><style>@page{@bottom-left{content:<?= json_encode($footer,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>}@bottom-right{content:"Page " counter(page) " of " counter(pages)}}</style></head><body class="<?= !empty($model['transaction_presentation'])?'tx-export-page':'' ?>"><main class="fx-page"><header><p><?= !empty($model['transaction_presentation'])?'Atikha Finance':'ATIKHA FINANCE · READ ONLY' ?></p><h1><?= $e($model['title']) ?></h1><p>All matching results · generated <?= $e($model['generated_at']) ?></p><button class="fr-no-print" onclick="window.print()">Print / Save PDF</button></header><dl class="fx-meta"><?php foreach($model['metadata'] as $key=>$value):if($key==='Text protection')continue;?><div><dt><?= $e($key) ?></dt><dd><?= $e($value) ?></dd></div><?php endforeach;?></dl><?php foreach($sections as $section):?><section class="fx-section fx-kind-<?= $e($model['kind']) ?>"><?php if(empty($model['transaction_presentation'])): ?><h2><?= $e($section['title']) ?></h2><?php endif; ?><?php report_view_table($section['rows'],$section['columns'],$section['title'],$section['totals']);?></section><?php endforeach;?></main></body></html><?php
}catch(Throwable $e){if(is_resource($spool))fclose($spool);$status=($e instanceof ReportingProblem||$e instanceof JournalProblem||$e instanceof LedgerProblem)?$e->status:503;http_response_code($status);header('Content-Type: text/plain; charset=utf-8');if($status===503)error_log('Financial export failed: '.$e->getMessage());echo $status===503?'The export could not be completed. No partial file was sent. Try again or ask your administrator to check the report.':$e->getMessage();}
